/* Suhail's service worker.
 *
 * Hand-written rather than generated by next-pwa or @serwist/next. Both are
 * webpack plugins under the hood — next-pwa wraps Workbox's
 * GenerateSWWebpackPlugin, and @serwist/next's stable release depends on
 * @serwist/webpack-plugin the same way. This project builds with Turbopack
 * (confirmed by every `next build` in this repo printing "▲ Next.js
 * 16.2.11 (Turbopack)"), which does not execute webpack plugins. Installing
 * either package here would add a dependency that silently produces no
 * service worker, which is worse than not having one: a build-tool mismatch
 * hidden behind a config flag that looks like it worked.
 *
 * A static file in public/ needs no bundler cooperation at all, which is
 * what makes this the reliable option under Turbopack rather than the
 * fallback one.
 *
 * Scope: CLAUDE.md section 3 calls full offline mode a hard requirement
 * ("traveller may lose signal in the desert on their trip"), and section 12
 * asks specifically for the last-viewed experience and the last-viewed
 * booking to survive offline. This does exactly that plus the app shell —
 * not a generic precache-everything strategy, which would be both harder to
 * reason about by hand and larger than this product needs.
 */

const VERSION = "v1";
const SHELL_CACHE = `suhail-shell-${VERSION}`;
const RUNTIME_CACHE = `suhail-runtime-${VERSION}`;

/* Enough to render something coherent offline on a first visit: the offline
 * fallback itself, the two icon sizes the manifest points at, and the
 * manifest. Not the whole app shell's JS/CSS bundle — Next's build hashes
 * those filenames per deploy, so listing them by name here would go stale on
 * the very next build. Those get runtime-cached instead, the same as any
 * other request, the first time each one is actually fetched. */
const SHELL_URLS = ["/offline", "/manifest.webmanifest", "/icon/192", "/icon/512"];

/* Pages worth keeping offline once visited. Everything else is
 * network-first with no fallback: a stale copy of, say, /search's results
 * would just be wrong, and CLAUDE.md rule 12's whole point is not showing
 * a traveller something that is no longer true. An experience someone has
 * actually looked at, and a booking someone actually holds, are different —
 * those stay useful stale, because the alternative offline is nothing. */
const OFFLINE_WORTHY = [/^\/experiences\//, /^\/book\/confirmation\//, /^\/api\/bookings\//, /^\/trips$/];

/* FIFO cap on the runtime cache so "last viewed" does not grow into "every
 * page ever viewed this month". Trimmed on every write. */
const RUNTIME_CACHE_LIMIT = 30;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(SHELL_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== SHELL_CACHE && key !== RUNTIME_CACHE)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

async function trimRuntimeCache() {
  const cache = await caches.open(RUNTIME_CACHE);
  const keys = await cache.keys();
  const over = keys.length - RUNTIME_CACHE_LIMIT;
  if (over > 0) {
    /* cache.keys() returns insertion order, so the oldest entries are the
       first ones: a real FIFO, not an approximation of one */
    await Promise.all(keys.slice(0, over).map((key) => cache.delete(key)));
  }
}

async function networkFirst(request) {
  try {
    const response = await fetch(request);
    /* only cache what is actually worth keeping offline, and only real
       success responses — an opaque or error response cached here would
       replay that failure forever */
    if (response.ok && OFFLINE_WORTHY.some((pattern) => pattern.test(new URL(request.url).pathname))) {
      const cache = await caches.open(RUNTIME_CACHE);
      await cache.put(request, response.clone());
      await trimRuntimeCache();
    }
    return response;
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;
    if (request.mode === "navigate") {
      const offline = await caches.match("/offline");
      if (offline) return offline;
    }
    throw new Error("offline and nothing cached for this request");
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  /* only GET is cacheable, and cross-origin requests (Supabase, Mapbox
     tiles, the Unsplash placeholders) are left to the network entirely —
     caching someone else's API responses under this product's cache is not
     this service worker's job */
  if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) {
    return;
  }

  event.respondWith(networkFirst(request));
});
